\section{Preliminaries}\label{sec: prelims}

\subsection{The Sum-of-Squares framework}
\label{subsec:sos-framework}

\begin{definition}[Pseudo-distribution]
A \emph{degree-$\ell$ pseudo-distribution} is a finitely-supported function $D:\R^m \rightarrow \R$ such that $\sum_{x} D(x) = 1$ and $\sum_{x} D(x) p(x)^2 \geq 0$ for every polynomial $p$ of degree at most $\ell/2$, where the summation is over all $x$ in the support of $D$.
\end{definition}

\begin{definition}[Pseudo-expectation]
The \emph{pseudo-expectation} of a function $f$ on $\R^m$ with respect to a pseudo-distribution $\mu$, denoted by $\pexpecf{\mu(x)}{f(x)}$,  is defined as
\begin{equation*}
  \pexpecf{\mu(x)}{f(x)} = \sum_{x} \mu(x) f(x).
\end{equation*}
\end{definition}

\begin{definition}[Constrained pseudo-distributions]
\label{def:constrained-pseudo-distributions}
Let $\mu$ be a degree-$\ell$ pseudo-distribution over $\mathbb{R}^d$. Let $\calA = \Set{ p_1\geq 0 , p_2\geq0 , \ldots p_m\geq 0}$ be a system of $m$ polynomial inequality constraints of degree at most $r$. We define $\mu$ to satisfy $\calA$ at degree $\ell \ge1$ if for every subset $\calS \subset [m]$, and every sum-of-squares polynomial $q$ such that $\textrm{deg}(q) + \sum_{i \in \calS } \max\Paren{p_i, r } \leq \ell$, $\pexpecf{\mu}{ q \prod_{i \in \calS} p_i } \geq 0$. Further, we define $\mu$ to \textit{ approximately satisfy} the system of constraints $\calA$ if the above inequalities are satisfied up to additive error $2^{-n^{\ell} } \norm{q} \prod_{i \in \calS} \norm{p_i}$, where $\norm{\cdot}$ denotes the euclidean norm of the coefficients of the polynomial, represented in the monomial basis.  
\end{definition}

\subsection{Re-weighting Pseudo-distributions}
\label{subsec:re-weighting-background}
Let $\mu$ be a pseudo-distribution of degree $\geq t$ on $d$-dimensional vector valued indeterminate $v$. Let $q$ be a sum-of-squares polynomial in $v$ of degree $t'<t$. Then, $\mu'$ defined by $\mu'(v) = \mu(v) \cdot q(v)$ is called the \emph{reweighting} of $\mu$ by the polynomial $q$. It is easy to observe that $\mu'$ is a pseudo-distribution of degree at least $t-t'$. Further, if $\mu$ satisfying a polynomial equality constraint $\{r=0\}$ and degree of $r$ is at most $t-t'$, then, so does $\mu'$.  

\subsection{Distributions}

\begin{definition}[Certifiable Hypercontractivity of linear forms]
\label{def:certifiable-hypercontractivity-of-linear}
An  distribution $\calD$ on $\R^d$ is said to be $h$-certifiably $c_h$-hypercontractive if there's a degree-$h$ sum-of-squares proof of the following unconstrained polynomial inequality in $d$-dimensional vector-valued indeterminate $v$:
\[ \E_{x \sim \calD} \iprod{x,v}^{2h} \leq \paren{c_h}^{2h} \Paren{\E_{x \sim \calD} \iprod{ x,v }^2 }^{h},
\]
for $h$ being an even integer.
A set of points $X \subseteq \R^d$ is said to be  $(c_h, h)$-certifiably hypercontractive if the uniform distribution on $X$ is  $h$-certifiably $c_h$-hypercontractive.
\end{definition}

\begin{definition}[Certifiable Hypercontractivity of quadratic forms]
\label{def:certifiable-hypercontractivity}
An isotropic distribution $\calD$ on $\R^d$ is said to be $h$-certifiably $c_h$-hypercontractive if there's a degree $h$ sum-of-squares proof of the following unconstrained polynomial inequality in $d \times d$ matrix-valued indeterminate $Q$:
\[ \E_{x \sim \calD} \Paren{x^{\top}Qx - \expecf{x\sim \calD}{ x^\top Q x} }^{2h} \leq \paren{c_h}^{2h} \Paren{\E_{x \sim \calD} \Paren{x^{\top}Qx - \expecf{x\sim \calD}{ x^\top Q x} }^2}^{h},
\]
for $h$ being an even integer.
A set of points $X \subseteq \R^d$ is said to be  $(c_h, h)$-certifiably hypercontractive if the uniform distribution on $X$ is  $h$-certifiably $c_h$-hypercontractive.
\end{definition}

\begin{definition}[Almost $k$-wise independent]
\label{def:k-wise-independent}
For an integer $k \ge 1$, define a distribution $\calD$ to be almost $k$-wise independent if for all subsets $S \subseteq [n]$ of size at most $k$, we have $\EE_{x \sim \calD} [\prod_{i \in S} x_i^2] = (1 \pm \gam_S) \prod_{i \in S} \EE_{x \sim \calD}[x_i^2]$ where $\gam_S = o_d(1)$.
\end{definition}

\begin{definition}[Strictly sub-exponential distribution]
\label{def:strictly-sub-exponential}
A distribution $\calD$ with mean $\mu$ and covariance $\Sigma$ is $\eps$-strictly sub-exponential if for all $v \in \R^d$, 
\begin{equation*}
    \Pr[ \abs{ \Iprod{x - \mu, v} } \geq t \sqrt{ v^\top \Sigma v} ] \leq \exp\Paren{ -t^{1+\eps} / c  },
\end{equation*}
for some constant $c$. 
\end{definition}

\begin{definition}[$(\delta,k, \eps)$-Reasonably anti-concentrated distributions]
\label{def:reasonably-anti-concentrated-dist}
A distribution $\calD$ with mean $0$ and covariance $\Sigma$ is $(\delta,k,\eps)$-reasonably anti-concentrated if it satisfies the following:
\begin{enumerate}
    \item $\calD$ is $\delta$-anti-concentrated
    \item $\calD$ is $\eps$-strictly sub-exponential.
    \item $\calD$ has $\exp\Paren{ (1/\delta^2)^{ \exp( 1/\delta^4) } }$-certifiably $O(1)$-hypercontractive linear forms. 
